// Nitro middleware that serves the prebuilt static landing page at "/" so the
// site entry renders without any framework JavaScript. The document is
// generated by scripts/gen-static-landing.mjs after the client build. If that
// file is missing, this handler falls through to the TanStack SSR renderer
// (h3 passes control to the next layer when a handler returns nothing).
//
// biome-ignore lint: the nitro plugin config casts the handlers array to any,
// and h3's typings don't model middleware fall-through, so `any` is used here.
import { existsSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { defineEventHandler, getRequestHeader, setResponseHeader } from "h3";

function staticRoot(): string {
	let dir = (import.meta as { dir?: string }).dir ?? "";
	if (!dir && typeof import.meta.url === "string") {
		dir = new URL(".", import.meta.url).pathname;
	}
	return dir;
}

function findLandingFile(extension: string): string | null {
	let dir = staticRoot();
	for (let depth = 0; depth < 5; depth++) {
		const candidate = join(dir, "public", `index.html${extension}`);
		if (existsSync(candidate)) return candidate;
		const parent = join(dir, "..");
		if (parent === dir) return null;
		dir = parent;
	}
	return null;
}

function etagFor(filePath: string): string | null {
	try {
		const stats = statSync(filePath);
		return `"${stats.size.toString(16)}-${Math.floor(stats.mtimeMs).toString(16)}"`;
	} catch {
		return null;
	}
}

function readVariant(encodings: string): {
	body: Buffer;
	encoding: string | null;
	plain: string;
} | null {
	const plainFile = findLandingFile("");
	if (!plainFile) return null;
	const plain = readFileSync(plainFile);
	if (encodings.includes("br")) {
		const brotliFile = findLandingFile(".br");
		if (brotliFile) {
			return { body: readFileSync(brotliFile), encoding: "br", plain };
		}
	}
	if (encodings.includes("gzip")) {
		const gzFile = findLandingFile(".gz");
		if (gzFile) {
			return { body: readFileSync(gzFile), encoding: "gzip", plain };
		}
	}
	return { body: plain, encoding: null, plain };
}

// biome-ignore lint/suspicious/noExplicitAny: h3 middleware typings don't
// support "return undefined to continue", which this handler needs.
export default defineEventHandler(async (event: any) => {
	const method = String(event.method ?? "GET").toUpperCase();
	if (method !== "GET" && method !== "HEAD") return undefined;

	// SSR generator bypass (scripts/gen-static-landing.mjs)
	if (getRequestHeader(event, "x-ssr-bypass") === "static-gen") {
		return undefined;
	}

	const pathname = String(event.path ?? "/").split("?")[0];
	if (pathname !== "/" && pathname !== "/index.html") return undefined;

	const variant = readVariant(getRequestHeader(event, "accept-encoding") ?? "");
	if (!variant) return undefined;

	const etag = etagFor(findLandingFile("") as string);
	setResponseHeader(event, "content-type", "text/html; charset=utf-8");
	setResponseHeader(
		event,
		"cache-control",
		"public, max-age=0, must-revalidate",
	);
	setResponseHeader(event, "vary", "accept-encoding");
	if (etag) {
		setResponseHeader(event, "etag", etag);
		if (getRequestHeader(event, "if-none-match") === etag) {
			return new Response(null, { status: 304, headers: { etag } });
		}
	}
	if (variant.encoding) {
		setResponseHeader(event, "content-encoding", variant.encoding);
	}
	return new Response(new Uint8Array(variant.body), {
		status: 200,
		headers: { "content-length": String(variant.body.byteLength) },
	});
});
